### Network GUID 출력 ###
uaac -k curl https://[OpsManager 도메인]/api/v0/staged/director/networks

### VM Deployment GUID 출력 ###
uaac -k curl https://[OpsManager 도메인]/api/v0/staged/products

### 적용 VM GUID 출력 ###
uaac -k curl https://[OpsManager 도메인]/api/v0/staged/products/[Deployment]/jobs

### Network GUID 입력 ###
curl -k http://[OpsManager 도메인]/api/v0/staged/products/[VM Deployment GUID]/jobs/[VM GUID]/resource_config \ 
  -H "Authorization: bearer $TOKEN" \
  -X PUT \
  -H "Content-type: application/json" \
  -d \
  '{
  "instance_type": {
    "id": "m6i.4xlarge"
  },
  "instances": 12,
  "additional_networks": [{
   "guid":["Network GUID"]
},
{
   "guid":["Network GUID"]
},
{
   "guid":["Network GUID"]
}],
  "internet_connected": false,
  "elb_names": [

  ],
  "additional_vm_extensions": [

  ],
  "swap_as_percent_of_memory_size": "automatic"
}' -vv
